  },
];

/** Constructed severity-dollar mix: volume ?? severity index, renormalized */
export function severityDollarShares(): {
  type: string;
  dollarSharePct: number;
}[] {
  const weighted = CLAIM_MIX.map((r) => ({
    type: r.type,
    w: (r.volumeSharePct / 100) * r.severityIndex,
  }));
  const sum = weighted.reduce((a, b) => a + b.w, 0);
  return weighted.map((r) => ({
    type: r.type,
    dollarSharePct: Math.round((1000 * r.w) / sum) / 10,
  }));
}

/** FBI IC3 2024 loss ladder (complaint dollars, $M) ??? fraud dominates; ransomware tiny $ */
export const IC3_LOSS_LADDER_2024: {
  category: string;
  lossM: number;
  confidence: Confidence;
}[] = [
