"use client";

import { useMemo, useState } from "react";
import {
  Area,
  Bar,
  CartesianGrid,
  Cell,
  ComposedChart,
  Legend,
  Line,
  Pie,
  PieChart,
  ResponsiveContainer,
  Scatter,
  ScatterChart,
  XAxis,
  YAxis,
  ZAxis,
} from "recharts";
import { Tooltip } from "@/components/charts/SortedTooltip";
import {
  CLAIM_MIX,
  EARNED_INCURRED_SERIES,
  GROWTH_COMPARE,
  HEADLINE,
  IC3_LOSS_LADDER_2024,
  PAID_RESERVE_WALK,
  POLICY_STRUCTURE_2024,
  PREMIUM_SERIES,
  SOURCE_NOTE,
  VIEW_OPTIONS,
  VIZ_MARKER,
  fmtB,
  fmtPct,
  indexSeries,
  severityDollarShares,
  type ScopeId,
  type ViewId,
} from "@/data/us-cyber-insurance-premiums-vs-incurred-losses-2026-data";

// viz-types: composed race, growth+LR lines, pie+scatter concentration, stacked paid/structure
// controls: view + domestic/total scope (or mix lens)

const COLORS = {
  premium: "#38bdf8",
  incurred: "#f97316",
  ratio: "#a855f7",
  paid: "#22c55e",
  reserve: "#eab308",
  ransom: "#ef4444",
  bec: "#0ea5e9",
  other: "#64748b",
  primary: "#38bdf8",
  excess: "#818cf8",
  endorsement: "#94a3b8",
};

const PIE_COLORS = [COLORS.bec, COLORS.ransom, COLORS.other];
const STRUCT_COLORS = [COLORS.primary, COLORS.excess, COLORS.endorsement];

function ChartCard({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="w-full min-w-0 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
      <div className="border-b border-slate-100 bg-slate-50 px-5 py-4">
        <h3 className="text-lg font-bold text-slate-900">{title}</h3>
        {subtitle && <p className="mt-1 text-sm text-slate-500">{subtitle}</p>}
      </div>
      <div className="p-4 sm:p-6">{children}</div>
    </div>
  );
}

function ToggleGroup<T extends string>({
  label,
  value,
  options,
  onChange,
}: {
  label: string;
  value: T;
  options: { id: T; label: string }[];
  onChange: (v: T) => void;
}) {
  return (
    <div className="flex flex-wrap items-center gap-2">
      <span className="text-xs font-semibold uppercase tracking-wide text-slate-500">
        {label}
      </span>
      <div className="inline-flex flex-wrap rounded-lg border border-slate-200 bg-white p.0.5">
        {options.map((o) => (
          <button
            key={o.id}
            type="button"
            onClick={() => onChange(o.id)}
            className={`rounded-md px-3 py-1.5 text-sm font-medium transition-colors ${
              value === o.id
                ? "bg-slate-900 text-white"
                : "text-slate-600 hover:bg-slate-50"
            }`}
          >
            {o.label}
          </button>
        ))}
      </div>
    </div>
  );
}

function StatStrip() {
  return (
    <div className="grid grid-cols-2 gap-3 sm:grid-cols-4">
      {[
        {
          label: "Domestic DWP 2024",
          value: fmtB(HEADLINE.domesticDwp2024B),
          sub: `${HEADLINE.domesticDwpYoyPct}% YoY`,
        },
        {
          label: "Loss ratio 2024",
          value: fmtPct(HEADLINE.lossRatio2024Pct),
          sub: `+${HEADLINE.lossRatioDeltaPp} pp vs 2023`,
        },
        {
          label: "Incurred (approx)",
          value: fmtB(HEADLINE.incurredApprox2024B),
          sub: `Paid ${fmtB(HEADLINE.paidLoss2024B)}`,
        },
        {
          label: "Ransomware severity tip",
          value: `~${HEADLINE.ransomwareClaimShareCoalitionPct}% of claims`,
          sub: `Avg ~$${HEADLINE.ransomwareAvgSeverityCoalitionK}k (Coalition)`,
        },
      ].map((s) => (
        <div
          key={s.label}
          className="rounded-lg border border-slate-100 bg-slate-50 px-3 py-2"
        >
          <div className="text-[11px] font-semibold uppercase tracking-wide text-slate-500">
            {s.label}
          </div>
          <div className="mt-0.5 text-lg font-bold text-slate-900">{s.value}</div>
          <div className="text-xs text-slate-500">{s.sub}</div>
        </div>
      ))}
    </div>
  );
}

function RacePanel({ scope }: { scope: ScopeId }) {
  const data = useMemo(() => {
    const idx = indexSeries(scope);
    return idx.map((r, i) => ({
      year: r.year,
      premiumB:
        scope === "domestic"
          ? PREMIUM_SERIES[i].domesticM / 1000
          : PREMIUM_SERIES[i].totalM / 1000,
      incurredB: EARNED_INCURRED_SERIES[i].incurredB,
      premiumIndex: r.premiumIndex,
      incurredIndex: r.incurredIndex,
    }));
  }, [scope]);

  return (
    <div className="grid gap-4 lg:grid-cols-2">
      <ChartCard
        title="Written premium vs reconstructed incurred"
        subtitle={
          scope === "domestic"
            ? "Domestic NAIC DWP ($B) vs earned??LR / paid+reserve incurred"
            : "Total DWP incl. alien surplus lines vs domestic incurred proxy"
        }
      >
        <div className="h-72 w-full min-w-0">
          <ResponsiveContainer width="100%" height="100%">
            <ComposedChart data={data} margin={{ top: 8, right: 12, left: 0, bottom: 0 }}>
              <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
              <XAxis dataKey="year" tick={{ fontSize: 12 }} />
              <YAxis tick={{ fontSize: 12 }} tickFormatter={(v) => `$${v}`} />
              <Tooltip />
              <Legend />
              <Bar dataKey="premiumB" name="Written premium ($B)" fill={COLORS.premium} radius={[4, 4, 0, 0]} />
              <Line
                type="monotone"
                dataKey="incurredB"
                name="Incurred ($B)"
                stroke={COLORS.incurred}
                strokeWidth={2.5}
                dot={{ r: 4 }}
              />
            </ComposedChart>
          </ResponsiveContainer>
        </div>
      </ChartCard>
      <ChartCard
        title="Index race (2020 = 100)"
        subtitle="Did premium outrun incurred? Hard-market years: yes. 2024: gap narrows."
      >
        <div className="h-72 w-full min-w-0">
          <ResponsiveContainer width="100%" height="100%">
            <ComposedChart data={data} margin={{ top: 8, right: 12, left: 0, bottom: 0 }}>
              <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
              <XAxis dataKey="year" tick={{ fontSize: 12 }} />
              <YAxis tick={{ fontSize: 12 }} />
              <Tooltip />
              <Legend />
              <Area
                type="monotone"
                dataKey="premiumIndex"
                name="Premium index"
                fill={COLORS.premium}
                fillOpacity={0.15}
                stroke={COLORS.premium}
                strokeWidth={2}
              />
              <Line
                type="monotone"
                dataKey="incurredIndex"
                name="Incurred index"
                stroke={COLORS.incurred}
                strokeWidth={2.5}
                dot={{ r: 4 }}
              />
            </ComposedChart>
          </ResponsiveContainer>
        </div>
      </ChartCard>
    </div>
  );
}

function RatioPanel() {
  return (
    <div className="grid gap-4 lg:grid-cols-2">
      <ChartCard
        title="YoY growth: premium vs incurred"
        subtitle="Domestic DWP growth vs reconstructed incurred growth; LR on right axis"
      >
        <div className="h-72 w-full min-w-0">
          <ResponsiveContainer width="100%" height="100%">
            <ComposedChart data={GROWTH_COMPARE} margin={{ top: 8, right: 8, left: 0, bottom: 0 }}>
              <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
              <XAxis dataKey="year" tick={{ fontSize: 12 }} />
              <YAxis yAxisId="g" tick={{ fontSize: 12 }} tickFormatter={(v) => `${v}%`} />
              <YAxis
                yAxisId="lr"
                orientation="right"
                domain={[30, 80]}
                tick={{ fontSize: 12 }}
                tickFormatter={(v) => `${v}%`}
              />
              <Tooltip />
              <Legend />
              <Bar
                yAxisId="g"
                dataKey="premiumYoyPct"
                name="Premium YoY %"
                fill={COLORS.premium}
                radius={[4, 4, 0, 0]}
              />
              <Bar
                yAxisId="g"
                dataKey="incurredYoyPct"
                name="Incurred YoY %"
                fill={COLORS.incurred}
                radius={[4, 4, 0, 0]}
              />
              <Line
                yAxisId="lr"
                type="monotone"
                dataKey="lossRatioPct"
                name="Loss ratio %"
                stroke={COLORS.ratio}
                strokeWidth={2.5}
                dot={{ r: 4 }}
              />
            </ComposedChart>
          </ResponsiveContainer>
        </div>
      </ChartCard>
      <ChartCard
        title="Earned premium vs incurred dollars"
        subtitle="2023???24 earned disclosed (Aon); earlier years constructed from written ?? LR band"
      >
        <div className="h-72 w-full min-w-0">
          <ResponsiveContainer width="100%" height="100%">
            <ComposedChart
              data={EARNED_INCURRED_SERIES}
              margin={{ top: 8, right: 12, left: 0, bottom: 0 }}
            >
              <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
