}

function RansomPanel({ mixLens }: { mixLens: "volume" | "severity" | "ic3" }) {
  const dollarShares = useMemo(() => severityDollarShares(), []);
  const pieData = useMemo(() => {
    if (mixLens === "volume") {
      return CLAIM_MIX.map((r) => ({ name: r.type, value: r.volumeSharePct }));
    }
    if (mixLens === "severity") {
      return dollarShares.map((r) => ({ name: r.type, value: r.dollarSharePct }));
    }
    return IC3_LOSS_LADDER_2024.filter((r) => r.lossM >= 12).map((r) => ({
      name: r.category,
      value: r.lossM,
    }));
  }, [mixLens, dollarShares]);

  const scatterData = CLAIM_MIX.map((r) => ({
    name: r.type,
    volume: r.volumeSharePct,
    severity: r.severityIndex,
    z: r.avgLossK ?? 80,
  }));

  return (
    <div className="grid gap-4 lg:grid-cols-2">
      <ChartCard
        title={
          mixLens === "ic3"
            ? "FBI IC3 2024 complaint-loss ladder ($M)"
            : mixLens === "severity"
              ? "Constructed insured severity-dollar mix"
              : "Insured claim volume mix (Coalition 2024)"
        }
        subtitle={
          mixLens === "ic3"
            ? "Fraud dominates IC3 dollars; ransomware $ is tiny ??? not an insurance severity map"
            : "Volume ??? dollars: ransomware ~21% of claims but severity tip"
        }
      >
        <div className="h-72 w-full min-w-0">
          <ResponsiveContainer width="100%" height="100%">
            <PieChart>
              <Pie
                data={pieData}
                dataKey="value"
                nameKey="name"
                cx="50%"
                cy="50%"
                innerRadius={55}
                outerRadius={95}
                paddingAngle={2}
              >
                {pieData.map((_, i) => (
                  <Cell
                    key={i}
                    fill={
                      mixLens === "ic3"
                        ? [COLORS.premium, COLORS.bec, COLORS.ratio, COLORS.paid, COLORS.reserve, COLORS.ransom][
                            i % 6
                          ]
                        : PIE_COLORS[i % PIE_COLORS.length]
                    }
                  />
                ))}
              </Pie>
              <Tooltip />
              <Legend />
            </PieChart>
          </ResponsiveContainer>
        </div>
      </ChartCard>
      <ChartCard
        title="Volume ?? severity scatter"
        subtitle="Bubble size ??? avg loss ($k where known). Ransomware sits high-severity / mid-volume."
      >
        <div className="h-72 w-full min-w-0">
          <ResponsiveContainer width="100%" height="100%">
            <ScatterChart margin={{ top: 12, right: 16, left: 0, bottom: 8 }}>
              <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
              <XAxis
                type="number"
                dataKey="volume"
                name="Volume share %"
                unit="%"
                tick={{ fontSize: 12 }}
                domain={[0, 70]}
              />
              <YAxis
                type="number"
                dataKey="severity"
                name="Severity index"
                tick={{ fontSize: 12 }}
                domain={[0, 110]}
              />
              <ZAxis type="number" dataKey="z" range={[80, 400]} />
              <Tooltip cursor={{ strokeDasharray: "3 3" }} />
              <Scatter data={scatterData} fill={COLORS.ransom}>
