};

const PIE_COLORS = [COLORS.bec, COLORS.ransom, COLORS.other];
const STRUCT_COLORS = [COLORS.primary, COLORS.excess, COLORS.endorsement];

function ChartCard({
  title,
  subtitle,
  children,
}: {
