      return CLAIM_MIX.map((r) => ({ name: r.type, value: r.volumeSharePct }));
    }
    if (mixLens === "severity") {
      return dollarShares.map((r) => ({ name: r.type, value: r.dollarSharePct }));
    }
    return IC3_LOSS_LADDER_2024.filter((r) => r.lossM >= 12).map((r) => ({
      name: r.category,
      value: r.lossM,
    }));
  }, [mixLens, dollarShares]);

  const scatterData = CLAIM_MIX.map((r) => ({
