                innerRadius={55}
                outerRadius={95}
                paddingAngle={2}
              >
                {pieData.map((_, i) => (
                  <Cell
                    key={i}
                    fill={
                      mixLens === "ic3"
                        ? [COLORS.premium, COLORS.bec, COLORS.ratio, COLORS.paid, COLORS.reserve, COLORS.ransom][
