                type="number"
                dataKey="volume"
                name="Volume share %"
                unit="%"
                tick={{ fontSize: 12 }}
                domain={[0, 70]}
              />
              <YAxis
                type="number"
                dataKey="severity"
                name="Severity index"
                tick={{ fontSize: 12 }}
                domain={[0, 110]}
              />
              <ZAxis type="number" dataKey="z" range={[80, 400]} />
              <Tooltip cursor={{ strokeDasharray: "3 3" }} />
              <Scatter data={scatterData} fill={COLORS.ransom}>
