          <span className="font-semibold text-slate-700">
            {fmtPct(dollarShares.find((d) => d.type === "Ransomware")?.dollarSharePct ?? 0, 1)}
          </span>{" "}
          of the indexed mix ??? concentration without claiming a NAIC census share.
        </p>
      </ChartCard>
    </div>
  );
}

function StructurePanel() {
