                        ? [COLORS.premium, COLORS.bec, COLORS.ratio, COLORS.paid, COLORS.reserve, COLORS.ransom][
                            i % 6
                          ]
                        : PIE_COLORS[i % PIE_COLORS.length]
                    }
                  />
                ))}
              </Pie>
              <Tooltip />
              <Legend />
            </PieChart>
          </ResponsiveContainer>
        </div>
      </ChartCard>
      <ChartCard
        title="Volume ?? severity scatter"
        subtitle="Bubble size ??? avg loss ($k where known). Ransomware sits high-severity / mid-volume."
      >
        <div className="h-72 w-full min-w-0">
          <ResponsiveContainer width="100%" height="100%">
            <ScatterChart margin={{ top: 12, right: 16, left: 0, bottom: 8 }}>
              <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
              <XAxis
                type="number"
                dataKey="volume"
                name="Volume share %"
                unit="%"
                tick={{ fontSize: 12 }}
                domain={[0, 70]}
              />
              <YAxis
                type="number"
                dataKey="severity"
                name="Severity index"
                tick={{ fontSize: 12 }}
                domain={[0, 110]}
              />
              <ZAxis type="number" dataKey="z" range={[80, 400]} />
              <Tooltip cursor={{ strokeDasharray: "3 3" }} />
              <Scatter data={scatterData} fill={COLORS.ransom}>
                {scatterData.map((d, i) => (
                  <Cell
                    key={d.name}
                    fill={PIE_COLORS[i % PIE_COLORS.length]}
                  />
                ))}
              </Scatter>
            </ScatterChart>
          </ResponsiveContainer>
        </div>
        <p className="mt-2 text-xs text-slate-500">
          Constructed severity-dollar share for ransomware ???{" "}
          <span className="font-semibold text-slate-700">
            {fmtPct(dollarShares.find((d) => d.type === "Ransomware")?.dollarSharePct ?? 0, 1)}
          </span>{" "}
          of the indexed mix ??? concentration without claiming a NAIC census share.
        </p>
      </ChartCard>
    </div>
  );
}

function StructurePanel() {
  const structPie = POLICY_STRUCTURE_2024.map((r) => ({
    name: r.structure,
    value: r.premiumSharePct,
  }));

  return (
    <div className="grid gap-4 lg:grid-cols-2">
      <ChartCard
        title="Paid loss vs reserve change"
        subtitle="2024 paid-to-incurred jumped to 76% (from 55%) as paid rose to $2.45B"
      >
        <div className="h-72 w-full min-w-0">
          <ResponsiveContainer width="100%" height="100%">
            <ComposedChart data={PAID_RESERVE_WALK} margin={{ top: 8, right: 8, left: 0, bottom: 0 }}>
              <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
              <XAxis dataKey="year" tick={{ fontSize: 12 }} />
              <YAxis tick={{ fontSize: 12 }} tickFormatter={(v) => `$${v}B`} />
              <Tooltip />
              <Legend />
              <Bar
                dataKey="paidB"
                name="Paid ($B)"
                stackId="a"
                fill={COLORS.paid}
                radius={[0, 0, 0, 0]}
              />
              <Bar
                dataKey="reserveChangeB"
                name="Reserve ?? ($B)"
                stackId="a"
                fill={COLORS.reserve}
                radius={[4, 4, 0, 0]}
              />
              <Line
                type="monotone"
                dataKey="incurredB"
                name="Incurred ($B)"
                stroke={COLORS.incurred}
                strokeWidth={2.5}
                dot={{ r: 5 }}
              />
            </ComposedChart>
          </ResponsiveContainer>
        </div>
      </ChartCard>
      <ChartCard
        title="2024 premium by policy structure"
        subtitle="Primary 65% ?? Excess 31% ?? Endorsement 4% of domestic DWP"
      >
        <div className="h-72 w-full min-w-0">
          <ResponsiveContainer width="100%" height="100%">
            <PieChart>
              <Pie
                data={structPie}
                dataKey="value"
                nameKey="name"
                cx="50%"
                cy="50%"
                innerRadius={50}
                outerRadius={95}
                paddingAngle={2}
                label={({ name, value }) => `${name} ${value}%`}
              >
                {structPie.map((_, i) => (
                  <Cell key={i} fill={STRUCT_COLORS[i % STRUCT_COLORS.length]} />
                ))}
              </Pie>
              <Tooltip />
            </PieChart>
          </ResponsiveContainer>
        </div>
      </ChartCard>
    </div>
  );
}

export function UsCyberInsurancePremiumsVsIncurredLosses2026Dashboard() {
  const [view, setView] = useState<ViewId>("race");
  const [scope, setScope] = useState<ScopeId>("domestic");
  const [mixLens, setMixLens] = useState<"volume" | "severity" | "ic3">("severity");

  return (
    <div
      className="w-full space-y-4"
      data-viz={VIZ_MARKER}
      data-testid={VIZ_MARKER}
    >
      <div className="flex flex-col gap-3 sm:flex-row sm:flex-wrap sm:items-center sm:justify-between">
        <ToggleGroup
          label="Panel"
          value={view}
          options={VIEW_OPTIONS}
          onChange={setView}
        />
        {view === "race" && (
          <ToggleGroup
            label="Premium scope"
            value={scope}
            options={[
              { id: "domestic", label: "Domestic only" },
              { id: "total", label: "Incl. alien surplus" },
            ]}
            onChange={setScope}
          />
        )}
        {view === "ransom" && (
          <ToggleGroup
            label="Mix lens"
            value={mixLens}
            options={[
              { id: "severity", label: "Severity $" },
              { id: "volume", label: "Claim volume" },
              { id: "ic3", label: "IC3 crime $" },
            ]}
            onChange={setMixLens}
          />
        )}
      </div>

      <StatStrip />

      {view === "race" && <RacePanel scope={scope} />}
      {view === "ratio" && <RatioPanel />}
      {view === "ransom" && <RansomPanel mixLens={mixLens} />}
      {view === "structure" && <StructurePanel />}

      <p className="text-xs leading-relaxed text-slate-500">{SOURCE_NOTE}</p>
    </div>
  );
}

