/**
 * US cyber insurance premiums vs incurred losses ??? 2026 desk cut.
 * Core question: Did cyber written premium grow faster than incurred losses,
 * and how concentrated are insured losses in ransomware?
 *
 * Primary: NAIC Cybersecurity & Identity Theft Insurance Coverage Supplement
 *   (via NAIC 2025 Cybersecurity Insurance Report + Aon U.S. Cyber Market Update).
 * Secondary: FBI IC3 2024 Internet Crime Report; Coalition 2025 Cyber Claims Report
 *   (insured-book claim mix, not a census).
 */

export type Confidence = "disclosed" | "estimated" | "constructed";

export const VIZ_MARKER = "us-cyber-insurance-premiums-vs-incurred-losses-2026";

export const SOURCE_NOTE =
  "NAIC domestic figures are U.S.-domiciled statutory supplement prints; " +
  "total market adds alien surplus lines from the NAIC Cybersecurity Insurance Report. " +
  "Loss ratios are calendar-year incurred loss + defense & cost containment (DCC) " +
  "over earned premium (Aon extraction of the same supplement). " +
  "Incurred dollars for years without a published earned-premium print are " +
  "reconstructed as earned ?? LR or paid + reserve change and tagged constructed. " +
  "Coalition ransomware / BEC shares are one active-carrier book, not industry census. " +
  "FBI IC3 ransomware dollars are complaint-reported losses only ??? they exclude most " +
  "business-interruption and remediation costs that drive insurance severity. " +
  "Do not equate IC3 crime dollars with NAIC incurred insurance losses.";

export const SOURCES = [
  {
    label: "NAIC ??? Report on the Cybersecurity Insurance Market (2025)",
    url: "https://content.naic.org/sites/default/files/inline-files/2025_Cybersecurity_Insurance%20Report.pdf",
  },
  {
    label: "Aon ??? U.S. Cyber Market Update (2024 NAIC supplement)",
    url: "https://www.aon.com/getmedia/e8087f7c-d1c0-4d15-af60-f4e3fb72bbe0/2024-US-Cyber-Market-Update.pdf",
  },
  {
    label: "FBI IC3 ??? 2024 Internet Crime Report",
    url: "https://www.ic3.gov/AnnualReport/Reports/2024_IC3Report.pdf",
  },
  {
    label: "Coalition ??? 2025 Cyber Claims Report (2024 policy year)",
    url: "https://www.coalitioninc.com/blog/cyber-insurance/2025-cyber-claims-report",
  },
];

/** Headline desk stats */
export const HEADLINE = {
  domesticDwp2024B: 7.08,
  domesticDwp2023B: 7.25,
  domesticDwpYoyPct: -2.3,
  totalDwp2024B: 9.14,
  totalDwp2023B: 9.84,
  totalDwpYoyPct: -7.1,
  lossRatio2024Pct: 49,
  lossRatio2023Pct: 42,
  lossRatioDeltaPp: 7,
  earnedPremium2024B: 6.6,
  earnedPremium2023B: 7.4,
  incurredApprox2024B: 3.24,
  paidLoss2024B: 2.45,
  paidLoss2023B: 1.66,
  reserveIncrease2024M: 792,
  claims2024Approx: 50_000,
  claimsYoyPct: 40,
  premiumCagr2020to2022Pct: 62,
  incurredCagr2020to2022ApproxPct: 35,
  ransomwareClaimShareCoalitionPct: 21,
  becFtfClaimShareCoalitionPct: 60,
  ransomwareAvgSeverityCoalitionK: 292,
  ic3TotalLoss2024B: 16.6,
  ic3RansomwareLoss2024M: 12.5,
  ic3RansomwareComplaints2024: 3156,
  primaryPremiumShare2024Pct: 65,
  excessPremiumShare2024Pct: 31,
  endorsementPremiumShare2024Pct: 4,
  paidToIncurred2024Pct: 76,
  paidToIncurred2023Pct: 55,
  thirdPartyClaimShare2024Pct: 25,
};

export type ScopeId = "domestic" | "total";

/** Direct written premium series ($M) */
export const PREMIUM_SERIES: {
  year: number;
  domesticM: number;
  totalM: number;
  confidence: Confidence;
}[] = [
  { year: 2020, domesticM: 2754, totalM: 4065, confidence: "disclosed" },
  { year: 2021, domesticM: 4827, totalM: 6543, confidence: "disclosed" },
  { year: 2022, domesticM: 7265, totalM: 9686, confidence: "disclosed" },
  { year: 2023, domesticM: 7248, totalM: 9843, confidence: "disclosed" },
  { year: 2024, domesticM: 7083, totalM: 9144, confidence: "disclosed" },
];

/**
 * Domestic calendar-year loss ratio (incurred loss + DCC / earned premium).
 * 2022???2024: Aon from NAIC. 2020???2021: industry spike band (estimated).
 */
export const LOSS_RATIO_SERIES: {
  year: number;
  lossRatioPct: number;
  confidence: Confidence;
  note?: string;
}[] = [
  {
    year: 2020,
    lossRatioPct: 68,
    confidence: "estimated",
    note: "Hard-market spike band; Aon flags 2020???21 as materially above 2022???24",
  },
  {
    year: 2021,
    lossRatioPct: 65,
    confidence: "estimated",
    note: "Hard-market spike band; still elevated vs post-hardening years",
  },
  { year: 2022, lossRatioPct: 45, confidence: "disclosed" },
  { year: 2023, lossRatioPct: 42, confidence: "disclosed" },
  { year: 2024, lossRatioPct: 49, confidence: "disclosed" },
];

/**
 * Earned premium + reconstructed incurred (domestic, $B).
 * 2023???24 earned from Aon; earlier years use written as proxy for earned (tagged).
 */
export const EARNED_INCURRED_SERIES: {
  year: number;
  earnedB: number;
  incurredB: number;
  paidB: number | null;
  reserveChangeB: number | null;
  confidence: Confidence;
}[] = [
  {
    year: 2020,
    earnedB: 2.5,
    incurredB: 1.7,
    paidB: null,
    reserveChangeB: null,
    confidence: "constructed",
  },
  {
    year: 2021,
    earnedB: 4.2,
    incurredB: 2.73,
    paidB: null,
    reserveChangeB: null,
    confidence: "constructed",
  },
  {
    year: 2022,
    earnedB: 6.5,
    incurredB: 2.93,
    paidB: null,
    reserveChangeB: null,
    confidence: "constructed",
  },
  {
    year: 2023,
    earnedB: 7.4,
    incurredB: 3.11,
    paidB: 1.66,
    reserveChangeB: 1.45,
    confidence: "disclosed",
  },
  {
    year: 2024,
    earnedB: 6.6,
    incurredB: 3.24,
    paidB: 2.45,
    reserveChangeB: 0.792,
    confidence: "disclosed",
  },
];

/** Premium growth vs incurred growth (YoY %) for dual-axis growth panel */
export const GROWTH_COMPARE: {
  year: number;
  premiumYoyPct: number;
  incurredYoyPct: number;
  lossRatioPct: number;
}[] = [
  { year: 2021, premiumYoyPct: 75.3, incurredYoyPct: 60.6, lossRatioPct: 65 },
  { year: 2022, premiumYoyPct: 50.5, incurredYoyPct: 7.3, lossRatioPct: 45 },
  { year: 2023, premiumYoyPct: -0.2, incurredYoyPct: 6.1, lossRatioPct: 42 },
  { year: 2024, premiumYoyPct: -2.3, incurredYoyPct: 4.2, lossRatioPct: 49 },
];

/** 2024 premium mix by policy structure (NAIC / Aon) */
export const POLICY_STRUCTURE_2024: {
  structure: string;
  premiumSharePct: number;
  role: string;
}[] = [
  {
    structure: "Primary",
    premiumSharePct: 65,
    role: "Majority of earned $; LR tracks industry",
  },
  {
    structure: "Excess",
    premiumSharePct: 31,
    role: "Softer rates; higher LR pressure",
  },
  {
    structure: "Endorsement",
    premiumSharePct: 4,
    role: "High policy count, low $ / policy",
  },
];

/**
 * Claim-type concentration (Coalition 2024 book).
 * Volume shares disclosed; severity dollars constructed for viz (indexed).
 */
export const CLAIM_MIX: {
  type: string;
  volumeSharePct: number;
  severityIndex: number;
  avgLossK: number | null;
  confidence: Confidence;
  note: string;
}[] = [
  {
    type: "BEC / FTF",
    volumeSharePct: 60,
    severityIndex: 38,
    avgLossK: null,
    confidence: "disclosed",
    note: "Majority of claim count; lower average severity",
  },
  {
    type: "Ransomware",
    volumeSharePct: 21,
    severityIndex: 100,
    avgLossK: 292,
    confidence: "disclosed",
    note: "Most costly / disruptive event type on Coalition book",
  },
  {
    type: "Other cyber",
    volumeSharePct: 19,
    severityIndex: 45,
    avgLossK: null,
    confidence: "constructed",
    note: "Residual (breach, privacy, misc first/third party)",
  },
];

/** Constructed severity-dollar mix: volume ?? severity index, renormalized */
export function severityDollarShares(): {
  type: string;
  dollarSharePct: number;
}[] {
  const weighted = CLAIM_MIX.map((r) => ({
    type: r.type,
    w: (r.volumeSharePct / 100) * r.severityIndex,
  }));
  const sum = weighted.reduce((a, b) => a + b.w, 0);
  return weighted.map((r) => ({
    type: r.type,
    dollarSharePct: Math.round((1000 * r.w) / sum) / 10,
  }));
}

/** FBI IC3 2024 loss ladder (complaint dollars, $M) ??? fraud dominates; ransomware tiny $ */
export const IC3_LOSS_LADDER_2024: {
  category: string;
  lossM: number;
  confidence: Confidence;
}[] = [
  { category: "Investment fraud", lossM: 6570, confidence: "disclosed" },
  { category: "Business email compromise", lossM: 2770, confidence: "disclosed" },
  { category: "Tech support scams", lossM: 1460, confidence: "disclosed" },
  { category: "Personal data breach", lossM: 1450, confidence: "disclosed" },
  { category: "Cyber threats (agg.)", lossM: 1571, confidence: "disclosed" },
  { category: "Ransomware (IC3 $)", lossM: 12.5, confidence: "disclosed" },
];

/** Paid vs reserve walk for 2023???2024 (Aon) */
export const PAID_RESERVE_WALK: {
  year: number;
  paidB: number;
  reserveChangeB: number;
  incurredB: number;
}[] = [
  { year: 2023, paidB: 1.66, reserveChangeB: 1.45, incurredB: 3.11 },
  { year: 2024, paidB: 2.45, reserveChangeB: 0.792, incurredB: 3.24 },
];

/** Index series: premium and incurred rebased to 2020 = 100 (domestic) */
export function indexSeries(scope: ScopeId = "domestic"): {
  year: number;
  premiumIndex: number;
  incurredIndex: number;
  lossRatioPct: number;
}[] {
  const baseP =
    scope === "domestic"
      ? PREMIUM_SERIES[0].domesticM
      : PREMIUM_SERIES[0].totalM;
  const baseI = EARNED_INCURRED_SERIES[0].incurredB;
  return PREMIUM_SERIES.map((p, i) => {
    const prem = scope === "domestic" ? p.domesticM : p.totalM;
    const inc = EARNED_INCURRED_SERIES[i].incurredB;
    return {
      year: p.year,
      premiumIndex: Math.round((1000 * prem) / baseP) / 10,
      incurredIndex: Math.round((1000 * inc) / baseI) / 10,
      lossRatioPct: LOSS_RATIO_SERIES[i].lossRatioPct,
    };
  });
}

export function premiumForScope(scope: ScopeId, year: number): number {
  const row = PREMIUM_SERIES.find((r) => r.year === year);
  if (!row) return 0;
  return scope === "domestic" ? row.domesticM : row.totalM;
}

export function fmtB(n: number, digits = 2): string {
  return `$${n.toFixed(digits)}B`;
}

