  excessPremiumShare2024Pct: 31,
  endorsementPremiumShare2024Pct: 4,
  paidToIncurred2024Pct: 76,
  paidToIncurred2023Pct: 55,
  thirdPartyClaimShare2024Pct: 25,
};

export type ScopeId = "domestic" | "total";

/** Direct written premium series ($M) */
export const PREMIUM_SERIES: {
  year: number;
  domesticM: number;
  totalM: number;
  confidence: Confidence;
}[] = [
  { year: 2020, domesticM: 2754, totalM: 4065, confidence: "disclosed" },
  { year: 2021, domesticM: 4827, totalM: 6543, confidence: "disclosed" },
