/**
 * Domestic calendar-year loss ratio (incurred loss + DCC / earned premium).
 * 2022???2024: Aon from NAIC. 2020???2021: industry spike band (estimated).
 */
export const LOSS_RATIO_SERIES: {
  year: number;
  lossRatioPct: number;
  confidence: Confidence;
  note?: string;
}[] = [
  {
    year: 2020,
