              <YAxis tick={{ fontSize: 12 }} tickFormatter={(v) => `$${v}B`} />
              <Tooltip />
              <Legend />
              <Bar dataKey="earnedB" name="Earned ($B)" fill={COLORS.premium} radius={[4, 4, 0, 0]} />
