}

function RansomPanel({ mixLens }: { mixLens: "volume" | "severity" | "ic3" }) {
  const dollarShares = useMemo(() => severityDollarShares(), []);
  const pieData = useMemo(() => {
    if (mixLens === "volume") {
      return CLAIM_MIX.map((r) => ({ name: r.type, value: r.volumeSharePct }));
    }
    if (mixLens === "severity") {
      return dollarShares.map((r) => ({ name: r.type, value: r.dollarSharePct }));
    }
    return IC3_LOSS_LADDER_2024.filter((r) => r.lossM >= 12).map((r) => ({
      name: r.category,
      value: r.lossM,
    }));
  }, [mixLens, dollarShares]);

  const scatterData = CLAIM_MIX.map((r) => ({
    name: r.type,
    volume: r.volumeSharePct,
    severity: r.severityIndex,
    z: r.avgLossK ?? 80,
  }));

  return (
    <div className="grid gap-4 lg:grid-cols-2">
      <ChartCard
        title={
          mixLens === "ic3"
            ? "FBI IC3 2024 complaint-loss ladder ($M)"
            : mixLens === "severity"
              ? "Constructed insured severity-dollar mix"
              : "Insured claim volume mix (Coalition 2024)"
        }
