// controls: view + domestic/total scope (or mix lens)

const COLORS = {
  premium: "#38bdf8",
  incurred: "#f97316",
  ratio: "#a855f7",
  paid: "#22c55e",
  reserve: "#eab308",
  ransom: "#ef4444",
  bec: "#0ea5e9",
  other: "#64748b",
  primary: "#38bdf8",
  excess: "#818cf8",
  endorsement: "#94a3b8",
