      <p className="text-sm font-medium text-slate-600">{VIZ_MARKER}</p>
      <div className="flex flex-col gap-3 sm:flex-row sm:flex-wrap sm:items-center sm:justify-between">
        <ToggleGroup
          label="Panel"
          value={view}
          options={VIEW_OPTIONS}
          onChange={setView}
        />
        {view === "race" && (
          <ToggleGroup
            label="Premium scope"
            value={scope}
            options={[
              { id: "domestic", label: "Domestic only" },
              { id: "total", label: "Incl. alien surplus" },
            ]}
            onChange={setScope}
          />
        )}
        {view === "ransom" && (
          <ToggleGroup
            label="Mix lens"
            value={mixLens}
            options={[
              { id: "severity", label: "Severity $" },
              { id: "volume", label: "Claim volume" },
              { id: "ic3", label: "IC3 crime $" },
            ]}
            onChange={setMixLens}
          />
        )}
      </div>

      <StatStrip />

      {view === "race" && <RacePanel scope={scope} />}
      {view === "ratio" && <RatioPanel />}
      {view === "ransom" && <RansomPanel mixLens={mixLens} />}
      {view === "structure" && <StructurePanel />}

      <p className="text-xs leading-relaxed text-slate-500">{SOURCE_NOTE}</p>
    </div>
  );
}

